$ErrorActionPreference='Stop'
$outDir=Join-Path $PSScriptRoot '..\Test-Documents'; New-Item -ItemType Directory -Force $outDir|Out-Null
function P($d,$s,$style='Normal'){ $p=$d.Content.Paragraphs.Add();$p.Range.Style=$style;$p.Range.Text=$s;$p.Range.InsertParagraphAfter() }
function T($d,$h,$rows){if($rows.Count -gt 0 -and $rows[0] -isnot [array]){$rows=@(,$rows)};$r=$d.Content;$r.Collapse(0);$t=$d.Tables.Add($r,$rows.Count+1,$h.Count);$t.Style='Table Grid';for($c=1;$c -le $h.Count;$c++){$t.Cell(1,$c).Range.Text=$h[$c-1];$t.Cell(1,$c).Range.Bold=1};for($i=0;$i -lt $rows.Count;$i++){for($c=0;$c -lt $h.Count;$c++){$t.Cell($i+2,$c+1).Range.Text=[string]$rows[$i][$c]}};$t.AutoFitBehavior(1);$d.Content.Paragraphs.Add()|Out-Null}
function Cases($d,$items){foreach($x in $items){P $d "$($x[0]) - $($x[1])" 'Heading 2';T $d @('Test Case Description','Test Procedure','Expected Results','Pre-conditions','Status') @(@($x[1],$x[2],$x[3],$x[4],'Not Run'))}}
function Report($file,$title,$cases,$mods){$w=New-Object -ComObject Word.Application;$w.Visible=$false;$d=$w.Documents.Add();P $d "$title TEST REPORT DOCUMENT" 'Title';T $d @('Project Name','Creator','Issue Date','Version') @(@('SWP391-G5 Bakery Management System','TinDLB',(Get-Date -Format yyyy-MM-dd),'1.0'));P $d 'Record of change' 'Heading 1';T $d @('Effective Date','Version','Change Item','Change description','Reference') @(@((Get-Date -Format yyyy-MM-dd),'1.0','A','Revised integration test document containing only TinDLB functions','Integration-Test.xlsx'));P $d 'TEST CASE LIST' 'Heading 1';$list=@();for($i=0;$i -lt $mods.Count;$i++){$list+=,@(($i + 1),$mods[$i][0],$mods[$i][0].Split(' ')[0],$mods[$i][1],$mods[$i][2])};T $d @('No','Function Name','Sheet Name','Description','Pre-Condition') $list;P $d 'Test Environment Setup Description' 'Heading 1';P $d 'Server: ASP.NET Core 8 application. Database: SQL Server configured by the project. Browser: Microsoft Edge or Google Chrome. Test accounts: Admin, Baker, Staff and Customer as stated by each case. Test data: active products, recipes, ingredients, orders, users and notifications.';P $d 'TEST STATISTICS' 'Heading 1';$st=@();foreach($m in $mods){$n=@($cases|?{$_.Count -gt 5 -and $_[5] -eq $m[0]}).Count;$st+=,@(($st.Count + 1),$m[0].Split(' ')[0],0,0,$n,0,$n)};T $d @('No','Module code','Passed','Failed','Pending','N/A','Number of test cases') $st;P $d 'All cases are Not Run until execution evidence is recorded. This report includes only the seven functions assigned to TinDLB.';foreach($m in $mods){$q=@($cases|?{$_.Count -gt 5 -and $_[5] -eq $m[0]});if($q.Count){P $d $m[0] 'Heading 1';Cases $d $q}};$d.SaveAs2($file,16);$d.Close();$w.Quit()}
$it=@(
@('IT-PT-001','Create and assign production task','Admin creates task with active product/recipe, quantity, Baker and future deadline.','Task is Assigned; recipe ingredients and quantities are saved; Baker and Admin receive notifications.','Admin authenticated; active recipe and Baker exist.','37 Production Task Management'),
@('IT-PT-002','Reject invalid production task','Submit with no active recipe, invalid Baker or past deadline.','Validation is returned and no task or notification is inserted.','Invalid test data exists.','37 Production Task Management'),
@('IT-PT-003','Preview ingredient requirements','Call IngredientRequirements with valid and non-positive product/quantity.','Valid input returns required/available/stock/shortage; invalid input returns empty JSON.','Active recipe and ingredients exist.','37 Production Task Management'),
@('IT-PT-004','Edit and recalculate task','Edit product, quantity, Baker, deadline and note.','Old ingredients are replaced; quantities recalculate; reassignment notifications are sent.','Task is not Completed/Cancelled; new recipe exists.','37 Production Task Management'),
@('IT-PT-005','Cancel production task','Cancel an Assigned or InProgress task, then repeat for completed task.','Cancellable task becomes Cancelled and notifications are created; completed task is rejected.','Admin authenticated; tasks exist.','37 Production Task Management'),
@('IT-PT-006','Filter production tasks','Query by status, numeric TaskId and product name.','Only matching tasks are returned with correct product and Baker names.','Tasks with different statuses/products exist.','37 Production Task Management'),
@('IT-NF-001','Persist assignment notification','Create or reassign a task and query notification records.','Type, recipient, title, message and timestamp are stored correctly.','Notification service and database are available.','38 Production Notifications'),
@('IT-NF-002','Persist shortage notification','Create a task where required ingredient quantity exceeds stock.','Task remains created; Admin and Baker receive shortage details.','Insufficient ingredient stock exists.','38 Production Notifications'),
@('IT-ST-001','Staff account validation','Create/edit staff with valid and invalid role/status/email data.','Valid data saves; invalid or duplicate data returns errors without corrupting existing data.','Admin authenticated.','35 Staff Account Management'),
@('IT-DB-001','Dashboard aggregation','Load Admin dashboard with orders, revenue, low-stock and production records.','View model totals match related database data.','Representative seed data exists.','39 Admin Dashboard'),
@('IT-OM-001','Order monitoring and filtering','Load order list and filter by status/search.','Only matching orders and correct details are returned.','Orders in multiple statuses exist.','40 Order Monitoring Admin'),
@('IT-RP-001','Revenue report and CSV export','Request report and CSV for a valid date range.','Totals match completed orders; CSV has expected headers and rows.','Completed orders exist.','30 Revenue Report'),
@('IT-STK-001','Low-stock alert','Load low-stock data and trigger Admin notification.','At/below-threshold ingredients are identified and alert is created.','Ingredients around threshold exist.','24 Admin Stock Alert Notification'))
$st=@(
@('ST-PT-001','Admin creates and assigns production task','Login Admin; create task; submit; inspect task list and notifications.','Task is Assigned with correct details; notifications are visible.','Admin, active Baker, product and recipe exist.','Production Planning'),
@('ST-PT-002','Insufficient ingredient warning','Create task requiring more ingredients than stock; inspect alerts.','Task is created and shortage warning is visible to Admin and Baker.','Recipe and low-stock ingredient exist.','Production Planning'),
@('ST-PT-003','Admin edits and reassigns task','Edit product, quantity, deadline, Baker and note; save; inspect results.','Task and ingredients update; new and previous Bakers are notified when reassigned.','Editable task and two active Bakers exist.','Production Planning'),
@('ST-PT-004','Admin cancels task','Cancel Assigned/InProgress task; refresh list and notifications.','Task displays Cancelled and cancellation notifications are available.','Cancellable task exists.','Production Planning'),
@('ST-NF-001','Baker receives assignment','Login Baker; open notifications, task list and detail.','Baker sees assignment and exact task details.','Admin has assigned a task to this Baker.','Production Execution'),
@('ST-NF-002','Baker completes production','Start task, enter actual yield and complete; Admin checks result.','Task transitions InProgress to Completed; inventory and history update.','Assigned task and sufficient stock exist.','Production Execution'),
@('ST-STAFF-001','Admin manages staff access','Create/edit staff, deactivate account, verify login and role pages.','Valid active user accesses allowed pages; inactive user is denied.','Admin and unique test user exist.','35 Staff Account Management'),
@('ST-DASH-001','Admin reviews dashboard','Open dashboard and compare cards/charts with source records.','Dashboard loads and totals are consistent.','Representative data exists.','39 Admin Dashboard'),
@('ST-ORDER-001','Admin monitors orders','Search/filter order list and open order detail.','Correct orders and details are displayed; filters remain applied.','Orders with different statuses exist.','40 Order Monitoring Admin'),
@('ST-REPORT-001','Admin views and exports revenue','Select date range, view report, download and open CSV.','Totals match completed orders and CSV is readable.','Completed orders exist in period.','30 Revenue Report'),
@('ST-STOCK-001','Admin receives low-stock alert','Use ingredients below/equal/above threshold; inspect dashboard/notifications.','Low-stock ingredients are alerted and normal stock is not falsely alerted.','Ingredients at multiple stock levels exist.','24 Admin Stock Alert Notification'))
$modsI=@(@('UC-37 Production Task Management','Create, edit, cancel and query tasks with recipes, users and ingredients.','Admin and database test data exist'),@('UC-38 Production Notifications','Persist task assignment, update, cancellation and shortage notifications.','Notification service configured'),@('UC-35 Staff Account Management','Validate and persist staff account changes.','Admin authenticated'),@('UC-39 Admin Dashboard','Aggregate operational data for Admin dashboard.','Representative data exists'),@('UC-40 Order Monitoring Admin','Query and filter customer orders.','Orders exist'),@('UC-30 Revenue Report','Calculate and export revenue data.','Completed orders exist'),@('UC-24 Admin Stock Alert Notification','Detect low-stock ingredients and notify Admin.','Ingredient thresholds configured'))
$modsS=@(@('Production Planning','Admin creates, updates and cancels production tasks through UI.','Admin, Baker, product, recipe and ingredient data exist'),@('Production Execution','Baker receives, starts and completes assigned tasks.','Assigned task and stock exist'),@('Staff Account Management','Admin manages staff and access behavior.','Admin and test staff exist'),@('Admin Dashboard','Admin reviews system metrics.','Representative data exists'),@('Order Monitoring','Admin monitors orders end-to-end.','Orders exist'),@('Revenue Report','Admin views and exports report.','Completed orders exist'),@('Stock Alert Notification','Admin receives low-stock warning.','Ingredients at multiple stock levels exist'))
